import{_ as r,g as i,o as s,c as n,j as t,a as d,k as o,a2 as l}from"./chunks/framework.DXa1R37q.js";const c={class:"diagram-links"},h=["href"],p={class:"diagram-frame"},m=["src"],_=JSON.parse('{"title":"How Neottia fits together","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"learn/index.md","filePath":"learn/index.md","lastUpdated":1792970147000}'),b={name:"learn/index.md"},u=Object.assign(b,{setup(f){const a=i("/diagrams/neottia-system.html");return(v,e)=>(s(),n("div",null,[e[0]||(e[0]=t("h1",{id:"how-neottia-fits-together",tabindex:"-1"},[d("How Neottia fits together "),t("a",{class:"header-anchor",href:"#how-neottia-fits-together","aria-label":'Permalink to "How Neottia fits together"'},"​")],-1)),e[1]||(e[1]=t("p",null,"Neottia separates portable lifecycle policy from host syntax and storage mechanics. A project configuration selects capabilities and harnesses. The compiler produces portable assets. Harness adapters project those assets into Pi, OpenCode, or Claude Code. Runtime capability packages then write canonical repository records through Repository Store.",-1)),t("div",c,[t("a",{href:o(a),target:"_blank",rel:"noreferrer"},"Open the interactive system map in a new tab",8,h)]),t("div",p,[t("iframe",{src:o(a),title:"Interactive Neottia system map",loading:"lazy"},null,8,m)]),e[2]||(e[2]=l('<h2 id="read-the-map-from-left-to-right" tabindex="-1" data-v-8228b550>Read the map from left to right <a class="header-anchor" href="#read-the-map-from-left-to-right" aria-label="Permalink to &quot;Read the map from left to right&quot;" data-v-8228b550>​</a></h2><ol data-v-8228b550><li data-v-8228b550><strong data-v-8228b550>Configuration</strong> — <code data-v-8228b550>.neottia/config.yml</code> selects modules, providers, roles, and installation targets.</li><li data-v-8228b550><strong data-v-8228b550>Compilation</strong> — the SDLC compiler renders six commands plus the shared operating protocol from explicit, checksummed inputs.</li><li data-v-8228b550><strong data-v-8228b550>Projection</strong> — one harness adapter converts portable assets into host paths, frontmatter, package entries, and MCP settings.</li><li data-v-8228b550><strong data-v-8228b550>Installation</strong> — the distribution layer plans mutations, rejects unowned conflicts, writes receipts, and supports rollback and recovery.</li><li data-v-8228b550><strong data-v-8228b550>Runtime</strong> — native extensions or stdio MCP servers expose the same domain tools.</li><li data-v-8228b550><strong data-v-8228b550>Repository data</strong> — canonical records are tracked with Git; SQLite indexes and Repository Store control state are disposable.</li></ol><h2 id="the-important-boundaries" tabindex="-1" data-v-8228b550>The important boundaries <a class="header-anchor" href="#the-important-boundaries" aria-label="Permalink to &quot;The important boundaries&quot;" data-v-8228b550>​</a></h2><ul data-v-8228b550><li data-v-8228b550>The compiler does not write files, invoke Git, contact providers, or grant host permissions.</li><li data-v-8228b550>Adapters describe host behavior but do not mutate the host directly.</li><li data-v-8228b550>The installer changes only receipt-owned paths or exact conflicts that a user approved.</li><li data-v-8228b550>Runtime tools use Repository Store for bounded mutation, lease control, journaling, durability, and recovery.</li><li data-v-8228b550>Canonical records remain the source of truth. Caches can be rebuilt.</li></ul><p data-v-8228b550>Continue with the <a href="/projects/neottia/learn/lifecycle" data-v-8228b550>lifecycle and approval model</a> or the <a href="/projects/neottia/learn/runtime-data" data-v-8228b550>runtime data flow</a>. For diagram evidence, pinned revisions, and license information, see <a href="/projects/neottia/reference/diagrams" data-v-8228b550>diagram sources and attribution</a>.</p>',5))]))}}),y=r(u,[["__scopeId","data-v-8228b550"]]);export{_ as __pageData,y as default};
